declare
  missing_retained integer;
  missing_deactivations integer;
  colliding_new_ids integer;
  colliding_titles integer;
begin
  if (select count(*) from typing_station_english_corpus_v2) <> 140
    or (select count(*) from typing_station_english_corpus_v2 where retained) <> 40
    or (select count(*) from typing_station_english_corpus_v2 where not retained) <> 100
    or (select count(*) from typing_station_english_corpus_v2_deactivate) <> 9 then
    raise exception 'Corpus v2 preflight failed: seed contract is not 40 updates, 9 deactivations, and 100 inserts';
