  select count(*) into missing_retained
  from typing_station_english_corpus_v2 seed
  left join public.passages passage on passage.id = seed.id and passage.language = 'english'
  where seed.retained and passage.id is null;

  select count(*) into missing_deactivations
  from typing_station_english_corpus_v2_deactivate seed
  left join public.passages passage on passage.id = seed.id and passage.language = 'english'
  where passage.id is null;

  select count(*) into colliding_new_ids
  from typing_station_english_corpus_v2 seed
  join public.passages passage on passage.id = seed.id
  where not seed.retained
    and (
      passage.language is distinct from 'english'
      or passage.title is distinct from seed.title
      or passage.category is distinct from seed.category
      or passage.style is distinct from seed.style
      or encode(digest(passage.content, 'sha256'), 'hex') is distinct from seed.sha256
      or passage.is_active is distinct from true
      or passage.is_public is distinct from true
    );

  select count(*) into colliding_titles
  from typing_station_english_corpus_v2 seed
  join public.passages passage on passage.title = seed.title and passage.id <> seed.id;

  if missing_retained <> 0 or missing_deactivations <> 0 or colliding_new_ids <> 0 or colliding_titles <> 0 then
    raise exception 'Corpus v2 preflight failed: missing retained %, missing deactivations %, new ID collisions %, title collisions %',
      missing_retained, missing_deactivations, colliding_new_ids, colliding_titles;
  end if;
end
$migration$;

update public.passages passage
set
  title = seed.title,
  category = seed.category,
  style = seed.style,
  content = seed.content,
  language = 'english',
  is_active = true,
  is_public = true,
  updated_at = now()
from typing_station_english_corpus_v2 seed
where seed.retained
  and passage.id = seed.id
  and passage.language = 'english';

update public.passages passage
set is_active = false, is_public = false, updated_at = now()
from typing_station_english_corpus_v2_deactivate seed
where passage.id = seed.id
  and passage.language = 'english';

insert into public.passages
  (id, title, category, style, content, language, is_active, is_public)
select id, title, category, style, content, 'english', true, true
from typing_station_english_corpus_v2
where not retained
on conflict (id) do update
set
  title = excluded.title,
  category = excluded.category,
  style = excluded.style,
  content = excluded.content,
  language = 'english',
  is_active = true,
  is_public = true,
  updated_at = now();

