    from typing_station_english_corpus_v2 seed
    join public.passages passage on passage.id = seed.id
    where passage.language = 'english' and passage.is_active and passage.is_public
    group by seed.category
    having count(*) <> 20
  ) category_counts;

  select count(*) into active_legacy from public.passages
  where language = 'english' and is_active and is_public
    and category in ('Random paragraph', 'Casual writing', 'News article', 'Business email',
      'Government / formal English', 'Tender / proposal writing', 'Legal / contract style');

  select count(*) into bad_hashes
  from typing_station_english_corpus_v2 seed
  join public.passages passage on passage.id = seed.id
  where encode(digest(passage.content, 'sha256'), 'hex') <> seed.sha256;

  select count(*) into retained_exact from typing_station_english_corpus_v2 seed
  join public.passages passage on passage.id = seed.id
